{
  "type": "object",
  "required": [
    "access_token",
    "token_type",
    "expires_in",
    "authorization_details"
  ],
  "properties": {
    "access_token": {
      "type": "string",
      "description": "[OAuth 2.0 Access Token](https://datatracker.ietf.org/doc/html/rfc6749#section-1.4) issued through Authorization Code grant."
    },
    "token_type": {
      "type": "string",
      "enum": [
        "Bearer"
      ],
      "description": "Access Token type."
    },
    "expires_in": {
      "type": "integer",
      "description": "Validity period of Access Token in seconds."
    },
    "scope": {
      "type": "string",
      "description": "[Access Token Scope](https://datatracker.ietf.org/doc/html/rfc6749#section-3.3) as sent in Authorization Request and granted by the End User."
    },
    "state": {
      "type": "string",
      "description": "OAuth 2.0 `state` value, provided as a means to support integrity checking by the Client under FAPI 2.0."
    },
    "refresh_token": {
      "type": "string",
      "description": "[OAuth 2.0 Refresh Token](https://datatracker.ietf.org/doc/html/rfc6749#section-1.5). Omitted from responses where not supported by a given consent type."
    },
    "id_token": {
      "type": "string",
      "description": "OpenID Connect ID Token, returned where applicable to requested scope and supported flows."
    },
    "authorization_details": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEAuthorizationEndpointsV21.AELodgedAuthorizationDetailsTypes"
      },
      "minItems": 1,
      "description": "Authorization details are sent in the Pushed Authorization Request"
    }
  },
  "additionalProperties": false
}

